var e={slug:`rpn`,influencerName:`Roberto Nickson`,influencerHandle:`@rpn`,influencerAvatarUrl:`https://res.cloudinary.com/pplx/image/upload/pplx-web/Computer/images/feature-research-browse.webp`,heroDescription:`I built this stock investment calculator entirely with Computer — no code, just a prompt. Try it below, see the exact prompt I used, then build your own.`,assetTitle:`Stock investment calculator`,screenshotUrl:`https://res.cloudinary.com/pplx/image/upload/pplx-web/Computer/images/feature-create-build.webp`,remixUrl:`https://www.perplexity.ai/computer/a/stockcalc-investment-calculato-LZTZjn2JTHG9TaCC2BVQHQ`,promptTitle:`Try Roberto's prompt`,promptText:`Build me a stock investment calculator that lets me input a ticker symbol, purchase price, number of shares, and current price. Show my total return, percentage gain/loss, and annualized return. Add a compound growth projector where I can model future value based on expected annual return over 5, 10, and 20 years. Include a clean, modern UI with clear labels, formatted currency values, and color-coded gains (green) and losses (red). Make it responsive and easy to use on both desktop and mobile.`};export{e as default};
